import SwiftUI
import SwiftData

struct ContentView: View { var body: some View { TabView { TodayView().tabItem { Label("今天", systemImage: "sun.max.fill") }; GrowthView().tabItem { Label("成长", systemImage: "chart.line.uptrend.xyaxis") }; ProfileView().tabItem { Label("我的", systemImage: "person.crop.circle") } }.tint(.indigo) } }
struct TodayView: View { @Environment(\.modelContext) private var context; @Query private var items: [Item]; @Query private var completions: [Completion]; @Query private var progressItems: [Progress]; @State private var showAdd = false; @State private var message = ""; @State private var showMessage = false; private var progress: Progress { progressItems.first ?? Progress() }; var body: some View { NavigationStack { List { Section { VStack(alignment: .leading) { Text("把今天的一点行动，记成成长。").font(.title3.bold()); Text("Lv.\(progress.level, specifier: "%.1f")  ·  \(progress.totalXP) XP").foregroundStyle(.secondary) }.padding(.vertical, 8) }; Section("今日行动") { if items.isEmpty { ContentUnavailableView("今天还没有任务", systemImage: "checkmark.circle", description: Text("创建一个值得完成的现实行动吧")) }; ForEach(items) { item in HStack { Button { complete(item) } label: { Image(systemName: isCompleted(item) ? "checkmark.circle.fill" : "circle").foregroundStyle(isCompleted(item) ? .green : .indigo).font(.title2) }.buttonStyle(.plain); VStack(alignment: .leading) { Text(item.title); Text("\(item.dimension.title) · \(item.xp) XP").font(.caption).foregroundStyle(.secondary) }; Spacer() } } } }.navigationTitle("今天").toolbar { Button { showAdd = true } label: { Image(systemName: "plus") } }.sheet(isPresented: $showAdd) { AddTaskView() }.alert("完成了一件事", isPresented: $showMessage) { Button("继续行动") {} } message: { Text(message) } } }; private func isCompleted(_ item: Item) -> Bool { completions.contains { $0.itemID == item.id && Calendar.current.isDateInToday($0.date) } }; private func complete(_ item: Item) { guard !isCompleted(item) else { return }; context.insert(Completion(itemID: item.id, xp: item.xp)); let p = progressItems.first ?? { let p = Progress(); context.insert(p); return p }(); p.totalXP += item.xp; try? context.save(); message = "获得 +\(item.xp) XP"; showMessage = true } }
struct AddTaskView: View { @Environment(\.dismiss) private var dismiss; @Environment(\.modelContext) private var context; @State private var title = ""; @State private var minutes = 30; @State private var difficulty = 3; @State private var dimension: LifeDimension = .learning; @State private var recurrence: Recurrence = .once; private var xp: Int { GrowthEngine.recommendedXP(minutes: minutes, difficulty: difficulty) }; var body: some View { NavigationStack { Form { TextField("例如：学习英语 30 分钟", text: $title); Picker("生活维度", selection: $dimension) { ForEach(LifeDimension.allCases) { Text($0.title).tag($0) } }; Picker("重复", selection: $recurrence) { ForEach(Recurrence.allCases) { Text($0.title).tag($0) } }; Stepper("预计 \(minutes) 分钟", value: $minutes, in: 5...240, step: 5); Picker("难度 \(difficulty)/5", selection: $difficulty) { ForEach(1...5, id: \.self) { Text("\($0)").tag($0) } }; Text("系统推荐：\(xp) XP").foregroundStyle(.secondary) }.navigationTitle("新任务").toolbar { ToolbarItem(placement: .cancellationAction) { Button("取消") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("添加") { context.insert(Item(title: title, dimension: dimension, minutes: minutes, difficulty: difficulty, xp: xp, recurrence: recurrence)); try? context.save(); dismiss() }.disabled(title.trimmingCharacters(in: .whitespaces).isEmpty) } } } } }
struct GrowthView: View { @Query private var progressItems: [Progress]; private var p: Progress { progressItems.first ?? Progress() }; var body: some View { NavigationStack { List { Section { Text("Lv.\(p.level, specifier: "%.1f")").font(.largeTitle.bold()); Text("\(p.totalXP) XP · 长期积累的成长").foregroundStyle(.secondary) }; Section("六维状态") { ForEach(LifeDimension.allCases) { Label($0.title, systemImage: "circle.fill") } }; Section { Text("等级记录长期积累，状态记录最近 15 天。它们彼此独立。").foregroundStyle(.secondary) } }.navigationTitle("成长") } } }
struct ProfileView: View { var body: some View { NavigationStack { List { Section("我的") { Text("本地数据与隐私"); Text("现实奖励目标将在下一阶段加入") }; Section("产品") { Text("LIVELVL · 现实人生 RPG").foregroundStyle(.secondary) } }.navigationTitle("我的") } } }
